import SynQt
import QtQuick.Controls

ApplicationWindow {
    id: window

    property string notice: "Loading..."
    readonly property bool feedReady: Server.ready

    visible: true
    title: "Feed"

    Edge.onDenied: reason => window.notice = reason
    onFeedReadyChanged: {
        if (window.feedReady) {
            Server.load();
        }
    }

    Label {
        id: banner
        text: Server.loaded ? "" : window.notice
    }

    ListView {
        anchors.fill: parent
        anchors.topMargin: banner.height
        model: Server.rows
        delegate: Text {
            required property var model
            text: model.title
        }
    }
}

// SPDX-FileCopyrightText: 2026 Alexandre 'kidev' Poumaroux
// SPDX-License-Identifier: Apache-2.0

import SynQt

Edge {
    id: feed

    loaded: false

    function load() {
        if (!Caller.hasScope("user")) {
            Caller.emitDenied("Please sign in.");
            return;
        }
        Store.allows(Caller.identity.sub).then(ok => {
            if (!ok) {
                Caller.emitDenied("Not allowed.");
                return;
            }
            Feeds.fetch().then(rows => {
                feed.setRows(rows);
                feed.loaded = true;
            });
        });
    }
}

// SPDX-FileCopyrightText: 2026 Alexandre 'kidev' Poumaroux
// SPDX-License-Identifier: Apache-2.0

import SynQt

Store {
    id: access

    // Nothing here asks who is calling: this point lists one consumer, so nothing
    // else can acquire it.
    function allows(sub) {
        const rows = Db.query(
            "SELECT 1 FROM grants WHERE sub = ?", [sub]);
        return rows.length > 0;
    }
}

entities.schema:
CREATE TABLE IF NOT EXISTS grants (
    sub        TEXT PRIMARY KEY,
    granted_at TEXT NOT NULL
);

CREATE INDEX IF NOT EXISTS grants_by_date
    ON grants (granted_at);

