import SynQt

Feeds {
    id: upstream

    property var cached: []

    function fetch() {
        return upstream.cached;
    }

    Timer {
        interval: 30000
        running: true
        repeat: true
        triggeredOnStart: true
        onTriggered: Http.get("https://data.example/feed")
            .then(res => upstream.cached = res.body.rows)
    }
}
